// ── Validates the Create/Edit tournament payload (mirrors DB constraints) ──
function validateTournament(b, phone) {
  const errors = [];
  const err = m => errors.push(m);
  const str = (v, min, max, msg) => { const s = String(v ?? '').trim(); if (s.length < min || s.length > max) err(msg); return s; };
  const opt = (v, max, msg) => { if (v === undefined || v === null || String(v).trim() === '') return null; const s = String(v).trim(); if (s.length > max) err(msg); return s; };
  const oneOf = (v, list, msg) => { const s = String(v ?? '').toUpperCase(); if (!list.includes(s)) err(msg); return s; };
  const int = (v, min, max, msg) => { const n = Number(v); if (!Number.isInteger(n) || n < min || n > max) { err(msg); return min; } return n; };
  const bool = v => v === true || v === 1 || v === '1' || v === 'true';
  const ownKey = (k, prefix, msg, required = true) => {
    if (k === undefined || k === null || k === '') { if (required) err(msg); return null; }
    if (typeof k !== 'string' || !k.startsWith(prefix) || k.includes('..')) { err('An upload could not be verified. Please upload it again.'); return null; }
    return k;
  };
  const day = s => { const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s ?? '')); if (!m) return null; const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); return d.getUTCMonth() === +m[2] - 1 ? d : null; };
  const fmtDay = d => d.toISOString().slice(0, 10);
  const assets = `tournament_assets/${phone}/`;
  const SPORTS = ['CRICKET', 'FOOTBALL', 'BADMINTON', 'PICKLEBALL'];

  const sport = oneOf(b.sport, SPORTS, 'Choose a sport.');
  const out = {
    sport,
    name: str(b.name, 3, 100, 'Tournament name must be 3-100 characters.'),
    description: opt(b.description, 1000, 'Description must be under 1000 characters.'),
    logo_key: ownKey(b.logo_key, assets, 'Add a tournament logo.'),
    banner_key: ownKey(b.banner_key, assets, 'Banner upload is invalid.', false),
    category: oneOf(b.category, ['OPEN', 'CORPORATE', 'COMMUNITY', 'SCHOOL', 'COLLEGE', 'UNIVERSITY', 'OTHER'], 'Choose a category.'),
    city: str(b.city || 'Mumbai', 2, 50, 'Enter the city.'),
    area: str(b.area, 2, 100, 'Enter the area or locality.'),
    match_days: oneOf(b.match_days || 'ALL', ['WEEKEND', 'WEEKDAYS', 'ALL'], 'Choose match days.'),
    match_timing: oneOf(b.match_timing || 'BOTH', ['DAY', 'NIGHT', 'BOTH'], 'Choose match timing.'),
    };

  // Dates
  const start = day(b.start_date), end = day(b.end_date);
  const today = new Date(); today.setUTCHours(0, 0, 0, 0);
  if (!start) err('Choose a start date.'); else if (start < today) err('Start date cannot be in the past.');
  if (!end) err('Choose an end date.'); else if (start && end < start) err('End date must be on or after the start date.');
  if (start && end && (end - start) / 86400000 > 366) err('A tournament can last at most a year.');
  out.start_date = start ? fmtDay(start) : null;
  out.end_date = end ? fmtDay(end) : null;

  // Fees, prize, extras
  out.jersey_provided = bool(b.jersey_provided) ? 1 : 0;
  out.jersey_fee = int(b.jersey_fee ?? 0, 0, 100000, 'Jersey fee is invalid.');
  // Divisions (age groups / categories). Older apps send one set of settings: treat it as one division.
  const rawDivs = Array.isArray(b.divisions) && b.divisions.length ? b.divisions : [{ ...b, name: 'Open', id: null }];
  if (rawDivs.length > 8) err('Add up to 8 divisions.');
  const divisions = rawDivs.slice(0, 8).map(d => validateDivision(d || {}, sport, rawDivs.length, err));
  const names = divisions.map(d => d.name.toLowerCase());
  if (new Set(names).size !== names.length) err('Each division needs a different name.');
  out.divisions = divisions;
  // Summary on the tournament row: first division's format, total teams, highest fee.
  const first = divisions[0];
  out.format = first.format; out.group_count = first.group_count; out.qualify_per_group = first.qualify_per_group;
  out.max_teams = divisions.reduce((n, d) => n + d.max_teams, 0);
  out.squad_min = Math.min(...divisions.map(d => d.squad_min)); out.squad_max = Math.max(...divisions.map(d => d.squad_max));
  out.entry_fee = Math.max(...divisions.map(d => d.entry_fee));
  out.prize_type = first.prize_type; out.prize_details = first.prize_details;
  out.match_rules = first.match_rules; out.points = first.points;
  if (out.jersey_fee > Math.min(...divisions.map(d => d.entry_fee))) err('Jersey fee must be included in every division\'s entry fee.');
  if (out.jersey_fee > 0 && !out.jersey_provided) err('Jersey fee only applies when jerseys are provided.');
  out.jersey_print = out.jersey_provided ? oneOf(b.jersey_print || 'NAME_NUMBER', ['NAME_NUMBER', 'NUMBER', 'PLAIN'], 'Choose what is printed on jerseys.') : null;
  out.food_provided = bool(b.food_provided) ? 1 : 0;
  const MEALS = ['BREAKFAST', 'LUNCH', 'DINNER', 'SNACKS'];
  const meals = Array.isArray(b.meals) ? [...new Set(b.meals.map(m => String(m).toUpperCase()))] : [];
  if (meals.some(m => !MEALS.includes(m))) err('Unknown meal selected.');
  if (out.food_provided && !meals.length) err('Choose which meals are provided.');
  out.meals = out.food_provided ? meals.filter(m => MEALS.includes(m)).join(',') : '';

  // Deadlines
  const dt = s => { const d = new Date(String(s ?? '').replace(' ', 'T')); return isNaN(d) ? null : d; };
  const sqlDt = d => d.toISOString().slice(0, 19).replace('T', ' ');
  const reg = dt(b.registration_deadline);
  if (!reg) err('Choose a registration deadline.');
  else if (start && reg >= new Date(start.getTime() + 86400000)) err('Registration must close before the tournament starts.');
  out.registration_deadline = reg ? sqlDt(reg) : null;
  let chk = b.checklist_deadline ? dt(b.checklist_deadline) : (start ? new Date(start.getTime() - 3 * 86400000 + 86399000) : null);
  if (b.checklist_deadline && !chk) err('Checklist deadline is invalid.');
  out.checklist_deadline = (out.food_provided || out.jersey_provided) && chk ? sqlDt(chk) : null;

  // Grounds
  const grounds = Array.isArray(b.grounds) ? b.grounds.map(g => String(g ?? '').trim()).filter(Boolean) : [];
  if (!grounds.length) err('Add at least one ground.');
  if (grounds.length > 10) err('Add up to 10 grounds.');
  if (grounds.some(g => g.length > 100)) err('Ground names must be under 100 characters.');
  out.grounds = grounds.slice(0, 10);

  // UPI payment details (required when there is an entry fee)
  if (out.entry_fee > 0) {
    const pay = b.payment || {};
    const upi = String(pay.upi_id ?? '').trim();
    if (!/^[a-zA-Z0-9.\-_]{2,256}@[a-zA-Z]{2,64}$/.test(upi)) err('Enter a valid UPI ID, e.g. name@okaxis.');
    out.payment = { upi_id: upi, upi_name: str(pay.upi_name, 2, 100, 'Enter the name on the UPI account.'),
      qr_key: ownKey(pay.qr_key, `payment_qr/${phone}/`, 'UPI QR upload is invalid.', false),
      accept_cash: bool(pay.accept_cash) ? 1 : 0, note: opt(pay.note, 255, 'Payment note must be under 255 characters.') };
  } else out.payment = null;

  // Documents
  const docs = Array.isArray(b.documents) ? b.documents : [];
  if (docs.length > 10) err('Add up to 10 documents.');
  out.documents = docs.slice(0, 10).map(d => ({
    doc_type: oneOf(d?.doc_type, ['FLYER', 'RULES', 'SCHEDULE', 'OTHER'], 'Choose a document type.'),
    title: str(d?.title, 1, 100, 'Each document needs a title.'),
    file_key: ownKey(d?.file_key, assets, 'A document upload is invalid.'),
    mime_type: oneOf(d?.mime_type, ['APPLICATION/PDF', 'IMAGE/JPEG', 'IMAGE/PNG'], 'Documents must be PDF, JPG or PNG.').toLowerCase(),
    size_bytes: int(d?.size_bytes, 1, 10485760, 'Documents must be under 10 MB.'),
  }));

  // Sponsors
  const sponsors = Array.isArray(b.sponsors) ? b.sponsors : [];
  if (sponsors.length > 10) err('Add up to 10 sponsors.');
  out.sponsors = sponsors.slice(0, 10).map(s => {
    const link = opt(s?.link_url, 255, 'Sponsor links must be under 255 characters.');
    if (link && !/^https?:\/\/[^\s]+$/i.test(link)) err('Sponsor links must start with http:// or https://');
    return { id: Number.isInteger(Number(s?.id)) && s?.id !== null && s?.id !== undefined ? Number(s.id) : null,
      name: str(s?.name, 1, 80, 'Each sponsor needs a name.'), label: str(s?.label, 1, 40, 'Each sponsor needs a label, e.g. Title sponsor.'),
      is_title: bool(s?.is_title) ? 1 : 0, logo_key: ownKey(s?.logo_key, assets, 'Each sponsor needs a logo.'),
      banner_key: ownKey(s?.banner_key, assets, 'A sponsor banner upload is invalid.', false), link_url: link,
      tagline: opt(s?.tagline, 80, 'Sponsor taglines must be under 80 characters.') };
  });
  if (out.sponsors.filter(s => s.is_title).length > 1) err('Only one sponsor can be the title sponsor.');

  return { errors: [...new Set(errors)], data: out };
}


// ── One division: teams, format, rules, points, fee, prize, age limit ──
const TIEBREAKERS = {
  CRICKET: ['NRR', 'HEAD_TO_HEAD', 'WINS'],
  FOOTBALL: ['GOAL_DIFF', 'GOALS_FOR', 'HEAD_TO_HEAD', 'SHOOTOUT'],
  BADMINTON: ['GAMES_DIFF', 'POINT_DIFF', 'HEAD_TO_HEAD'],
  PICKLEBALL: ['GAMES_DIFF', 'POINT_DIFF', 'HEAD_TO_HEAD'],
};
const POINT_DEFAULTS = { CRICKET: [2, 1, 1, 0], FOOTBALL: [3, 1, 1, 0], BADMINTON: [2, 1, 1, 0], PICKLEBALL: [2, 1, 1, 0] };
const TIE_DEFAULTS = { CRICKET: ['NRR', 'HEAD_TO_HEAD'], FOOTBALL: ['GOAL_DIFF', 'GOALS_FOR', 'HEAD_TO_HEAD'], BADMINTON: ['GAMES_DIFF', 'POINT_DIFF', 'HEAD_TO_HEAD'], PICKLEBALL: ['GAMES_DIFF', 'POINT_DIFF', 'HEAD_TO_HEAD'] };

function validateDivision(b, sport, count, err) {
  const oneOf = (v, list, msg) => { const s = String(v ?? '').toUpperCase(); if (!list.includes(s)) err(msg); return s; };
  const int = (v, min, max, msg) => { const n = Number(v); if (!Number.isInteger(n) || n < min || n > max) { err(msg); return min; } return n; };
  const optInt = (v, min, max, msg) => (v === undefined || v === null || v === '') ? null : int(v, min, max, msg);
  const bool = v => v === true || v === 1 || v === '1' || v === 'true';
  const name = String(b.name ?? '').trim().replace(/\s+/g, ' ') || (count === 1 ? 'Open' : '');
  if (name.length < 1 || name.length > 40) err('Each division needs a name (up to 40 characters).');
  const label = count > 1 ? `${name}: ` : '';
  const d = { id: Number.isInteger(Number(b.id)) && b.id !== null && b.id !== undefined ? Number(b.id) : null, name: name.slice(0, 40) };

  d.min_age = optInt(b.min_age, 3, 99, `${label}Minimum age must be between 3 and 99.`);
  d.max_age = optInt(b.max_age, 3, 99, `${label}Maximum age must be between 3 and 99.`);
  if (d.min_age !== null && d.max_age !== null && d.min_age > d.max_age) err(`${label}Minimum age cannot be above the maximum age.`);

  d.format = oneOf(b.format, ['LEAGUE', 'KNOCKOUT', 'LEAGUE_KNOCKOUT'], `${label}Choose a format.`);
  d.max_teams = int(b.max_teams, 2, 128, `${label}Number of teams must be between 2 and 128.`);
  const squadDefaults = { CRICKET: [6, 25], FOOTBALL: [5, 25], BADMINTON: [1, 2], PICKLEBALL: [1, 2] }[sport] || [1, 40];
  d.squad_min = int(b.squad_min ?? squadDefaults[0], 1, 40, `${label}Minimum squad size is invalid.`);
  d.squad_max = int(b.squad_max ?? squadDefaults[1], 1, 40, `${label}Maximum squad size is invalid.`);
  if (d.squad_max < d.squad_min) err(`${label}Maximum squad size must be at least the minimum.`);
  if (d.format === 'LEAGUE_KNOCKOUT') {
    d.group_count = int(b.group_count, 1, 16, `${label}Number of groups must be between 1 and 16.`);
    d.qualify_per_group = int(b.qualify_per_group, 1, 8, `${label}Teams qualifying per group must be between 1 and 8.`);
    if (d.max_teams / d.group_count < 2) err(`${label}Each group needs at least 2 teams.`);
    if (d.qualify_per_group >= Math.ceil(d.max_teams / d.group_count)) err(`${label}Fewer teams must qualify than play in each group.`);
  } else { d.group_count = null; d.qualify_per_group = null; }

  d.entry_fee = int(b.entry_fee ?? 0, 0, 100000, `${label}Entry fee must be between ₹0 and ₹1,00,000.`);
  d.prize_type = oneOf(b.prize_type || 'NONE', ['NONE', 'CASH', 'TROPHY', 'BOTH'], `${label}Choose a prize type.`);
  const pd = b.prize_details == null || String(b.prize_details).trim() === '' ? null : String(b.prize_details).trim();
  if (pd && pd.length > 255) err(`${label}Prize details must be under 255 characters.`);
  d.prize_details = d.prize_type === 'NONE' ? null : pd;

  // Match rules per sport
  const r = b.match_rules || {};
  let rules = {};
  if (sport === 'CRICKET') {
    const type = oneOf(r.match_type || 'LIMITED_OVERS', ['LIMITED_OVERS', 'BOX', 'PAIR', 'TEST', 'THE_HUNDRED'], `${label}Choose a match type.`);
    rules = { match_type: type, ball_type: oneOf(r.ball_type || 'TENNIS', ['TENNIS', 'LEATHER', 'OTHER'], `${label}Choose a ball type.`),
      pitch_type: r.pitch_type ? oneOf(r.pitch_type, ['ROUGH', 'CEMENT', 'TURF', 'ASTROTURF', 'MATTING'], `${label}Choose a pitch type.`) : null,
      players_per_side: int(r.players_per_side ?? 11, 2, 11, `${label}Players per side must be between 2 and 11.`),
      last_batter: bool(r.last_batter) };
    if (type !== 'TEST') {
      rules.overs = int(r.overs, 1, 90, `${label}Overs per innings must be between 1 and 90.`);
      rules.overs_per_bowler = int(r.overs_per_bowler ?? Math.ceil(rules.overs / 5), 1, 90, `${label}Overs per bowler is invalid.`);
      if (rules.overs_per_bowler > rules.overs) err(`${label}Overs per bowler cannot exceed overs per innings.`);
      rules.powerplay_overs = int(r.powerplay_overs ?? 0, 0, 90, `${label}Powerplay overs is invalid.`);
      if (rules.powerplay_overs > rules.overs) err(`${label}Powerplay cannot be longer than the innings.`);
    }
  } else if (sport === 'FOOTBALL') {
    rules = { players_per_side: int(r.players_per_side ?? 7, 3, 11, `${label}Players per side must be between 3 and 11.`),
      half_minutes: int(r.half_minutes ?? 20, 3, 45, `${label}Half length must be 3-45 minutes.`),
      rolling_subs: bool(r.rolling_subs ?? true), extra_time: bool(r.extra_time), penalties: bool(r.penalties ?? true) };
  } else {
    rules = { event: oneOf(r.event || 'DOUBLES', ['SINGLES', 'DOUBLES', 'MIXED'], `${label}Choose singles, doubles or mixed.`),
      points_per_game: int(r.points_per_game ?? (sport === 'BADMINTON' ? 21 : 11), 5, 30, `${label}Points per game is invalid.`),
      games: int(r.games ?? 3, 1, 5, `${label}Number of games is invalid.`), win_by_two: bool(r.win_by_two ?? true) };
    if (rules.games % 2 === 0) err(`${label}Number of games must be odd (best of 1, 3 or 5).`);
    if (sport === 'PICKLEBALL') rules.scoring = oneOf(r.scoring || 'SIDE_OUT', ['SIDE_OUT', 'RALLY'], `${label}Choose a scoring type.`);
  }
  d.match_rules = rules;

  // Points table with an ordered list of tie-breakers
  const p = b.points || {};
  const [dw, dt, dn, dl] = POINT_DEFAULTS[sport] || [2, 1, 1, 0];
  const allowed = TIEBREAKERS[sport] || [];
  let tbs = Array.isArray(p.tiebreakers) ? p.tiebreakers.map(t => String(t).toUpperCase()) : (p.tiebreaker ? [String(p.tiebreaker).toUpperCase()] : TIE_DEFAULTS[sport]);
  tbs = [...new Set(tbs)];
  if (!tbs.length || tbs.some(t => !allowed.includes(t))) err(`${label}Choose the tie-breakers in order.`);
  tbs = tbs.filter(t => allowed.includes(t));
  d.points = { win: int(p.win ?? dw, 0, 10, `${label}Points for a win is invalid.`), tie: int(p.tie ?? dt, 0, 10, `${label}Points for a draw is invalid.`),
    no_result: int(p.no_result ?? dn, 0, 10, `${label}Points for no result is invalid.`), loss: int(p.loss ?? dl, 0, 10, `${label}Points for a loss is invalid.`),
    tiebreakers: tbs, tiebreaker: tbs[0] || null };
  return d;
}

const b = $in.body || {};
const { errors, data } = validateTournament(b, auth.phone);
if (errors.length) return [{ json: { ok: false, status: 422, body: { success: false, message: errors[0], errors } } }];
let code = b.code ? String(b.code).toUpperCase() : null;
if (code && !/^[A-Z0-9]{6}$/.test(code)) return [{ json: { ok: false, status: 422, body: { success: false, message: "Invalid tournament code." } } }];
const isNew = !code;
if (isNew) { const A = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; code = Array.from({ length: 6 }, () => A[Math.floor(Math.random() * A.length)]).join(''); }
return [{ json: { ok: true, phone: auth.phone, code, isNew, data: JSON.stringify(data) } }];

const $in = $input.first().json;

const v = $('Check & Validate').first().json;
const exists = Number($in.n) > 0;
if (v.isNew && exists) return [{ json: { ok: false, status: 409, body: { success: false, message: "Please tap Save again." } } }];
if (!v.isNew && !exists) return [{ json: { ok: false, status: 404, body: { success: false, message: "Tournament not found." } } }];
return [{ json: v }];

const $in = $input.first().json;

const r = $in;
const msg = String(r.message || r.error?.message || '');
if (msg || !r.code) {
  if (msg.includes('NOT_OWNER')) return [{ json: { ok: false, status: 403, body: { success: false, message: "You can only edit tournaments you organise." } } }];
  if (msg.includes('LOCKED')) return [{ json: { ok: false, status: 409, body: { success: false, message: "This tournament can no longer be edited." } } }];
  if (msg.includes('TEAMS_APPROVED')) return [{ json: { ok: false, status: 409, body: { success: false, message: "Teams have already paid, so the sport and dates, and the fee, format and groups of divisions with paid teams, can no longer be changed.", code: 'TEAMS_APPROVED' } } }];
  if (msg.includes('DIVISION_HAS_TEAMS')) return [{ json: { ok: false, status: 409, body: { success: false, message: "A division that teams have registered for cannot be removed." } } }];
  if (msg.includes('BAD_DIVISION') || msg.includes('NO_DIVISIONS')) return [{ json: { ok: false, status: 422, body: { success: false, message: "Something went wrong with the divisions. Please reopen the tournament and try again." } } }];
  if (msg.includes('MAX_TEAMS_TOO_LOW')) return [{ json: { ok: false, status: 422, body: { success: false, message: "A division cannot have fewer team places than the teams you have already approved in it." } } }];
  if (msg.includes('ONE_TITLE_SPONSOR')) return [{ json: { ok: false, status: 422, body: { success: false, message: "Only one sponsor can be the title sponsor." } } }];
  if (msg.includes('uq_code') || msg.includes('Duplicate')) return [{ json: { ok: false, status: 409, body: { success: false, message: "Please tap Save again." } } }];
  return [{ json: { ok: false, status: 500, body: { success: false, message: "Could not save the tournament. Please try again." } } }];
}
const isNew = $('Check & Validate').first().json.isNew;
return [{ json: { status: isNew ? 201 : 200, body: { success: true, code: r.code, status: r.status, created: isNew } } }];
